r = primitives.call(name='inspect_robowits_object_poses', names=['container','dustpan','screw'])
print(r.ok)
out = r.output
if isinstance(out, dict):
    for k,v in out.items():
        if k in ('objects','poses','entities'):
            for name, info in (v.items() if isinstance(v, dict) else enumerate(v)):
                print(name, {kk: vv for kk, vv in info.items() if kk in ('position','pos','bounds','aabb','min','max','size','extent')} if isinstance(info, dict) else info)
        else:
            print(k, str(v)[:300])
else:
    print(str(out)[:2000])

p = primitives.call(name='place_robowits_object_at', arm='right', object_name='screw',
                    target_position=[0.58, 0.0, 0.905], approach_height=0.10,
                    placement_tolerance=0.03, release_width=0.09,
                    evidence_handles=handles, max_steps=240, max_translation=0.25)
print('ok', p.ok)
out = p.output
if isinstance(out, dict):
    for k, v in out.items():
        print(k, str(v)[:400])
else:
    print(str(out)[:1500])
r2 = primitives.call(name='inspect_robowits_object_poses', names=['screw','container'])
if r2.ok:
    for n in ['screw','container']:
        print(n, r2.output['object_poses'][n]['pos'])

q = primitives.call(name='query_robowits_wrist_orientations', arm='right', object_name='screw')
print('q ok', q.ok)
qo = q.output
if isinstance(qo, dict):
    for k, v in qo.items():
        if k == 'candidates':
            for c in v[:8]:
                print('  cand', {kk: (round(vv, 4) if isinstance(vv, float) else vv) for kk, vv in c.items() if kk in ('yaw_offset','axis_angle','opening_axis','clearance','min_clearance','projected_width','object_extent_along_opening','score')})
        else:
            print(k, str(v)[:250])
r7 = primitives.call(name='inspect_robowits_object_poses', names=['screw'])
s = r7.output['object_poses']['screw']
print('screw', s['pos'], s['bounds'], s['euler'])

